-- Al Shaqab Horse Show 2026 - database setup. Paste into Supabase: SQL Editor -> New query -> Run.
-- STEP 1: put YOUR admin e-mail on the line marked  <<<  (the account you will sign in with on admin.html).

create table if not exists public.admins (email text primary key);
alter table public.admins enable row level security;   -- no policies: not readable through the API

create or replace function public.is_admin() returns boolean
language sql security definer set search_path = public stable as $$
  select exists (select 1 from public.admins where lower(email) = lower(coalesce(auth.jwt() ->> 'email', '')));
$$;

create table if not exists public.horses (
  id          uuid primary key default gen_random_uuid(),
  pos         bigint generated always as identity,
  class_no    int,
  class_name  text,
  horse_name  text,
  country     text,
  sex         text,
  birth_date  text,
  color       text,
  sire        text,
  dam         text,
  owner       text,
  paid        boolean not null default false,
  updated_at  timestamptz not null default now()
);
create table if not exists public.owner_contacts (
  owner text primary key, email text, phone text, updated_at timestamptz not null default now()
);
create table if not exists public.app_meta (key text primary key, value text);

alter table public.horses         enable row level security;
alter table public.owner_contacts enable row level security;
alter table public.app_meta       enable row level security;

-- everyone (the shared dashboard) can READ horses + last-updated; only the admin can change anything
create policy "read horses"       on public.horses   for select to anon, authenticated using (true);
create policy "admin write horses" on public.horses   for all    to authenticated using (public.is_admin()) with check (public.is_admin());
create policy "read meta"         on public.app_meta for select to anon, authenticated using (true);
create policy "admin write meta"  on public.app_meta for all    to authenticated using (public.is_admin()) with check (public.is_admin());
-- owner e-mail / phone: admin only (never visible on the shared dashboard)
create policy "admin contacts"    on public.owner_contacts for all to authenticated using (public.is_admin()) with check (public.is_admin());

-- live updates for the shared dashboard
alter publication supabase_realtime add table public.horses;

